EvalSuiteCreateRequest {
  "type": "object",
  "description": "Author-only suite-create body. A suite-level default `model` (and optional `provider`) applies to every test unless the test overrides it.",
  "required": [
    "name",
    "serverIds",
    "model",
    "tests"
  ],
  "properties": {
    "name": {
      "type": "string",
      "minLength": 1,
      "description": "Suite name."
    },
    "description": {
      "type": "string"
    },
    "serverIds": {
      "type": "array",
      "minItems": 1,
      "description": "Servers (by canonical project ID) the suite's cases run against.",
      "items": {
        "type": "string"
      }
    },
    "serverNames": {
      "type": "array",
      "description": "Optional display names, parallel to `serverIds`.",
      "items": {
        "type": "string"
      }
    },
    "hosts": {
      "type": "array",
      "description": "Clients (hosts) to attach the suite to, in attach order. A suite with no attached client reports none wherever it is listed, and a run has no host to select. Same shape as the PATCH `hosts` field.",
      "items": {
        "type": "object",
        "required": [
          "host"
        ],
        "properties": {
          "host": {
            "type": "string",
            "minLength": 1,
            "description": "Host name or id."
          },
          "servers": {
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1
            },
            "description": "Server names (as bound in the suite's environment) or project-server ids."
          }
        }
      }
    },
    "model": {
      "type": "string",
      "minLength": 1,
      "description": "Suite-level default model id (e.g. `anthropic/claude-haiku-4.5`). Used for any test that omits `model`."
    },
    "provider": {
      "type": "string",
      "description": "Optional suite-level default provider. When omitted, the provider is derived from a `provider/model` id."
    },
    "passCriteria": {
      "type": "object",
      "description": "The floor a run must clear, as a PERCENT in [0, 100] \u2014 80 means 80%. `minimumPassRatePercent` is the canonical spelling (the unit is in the name); `minimumPassRate` is the deprecated alias for it. Send exactly one. THE NAME DISAMBIGUATES THE UNIT: a value in (0, 1) is accepted on `minimumPassRatePercent`, where it unambiguously means a sub-1% floor the evaluator can act on, and REJECTED on the bare `minimumPassRate`, where `0.8` cannot be told apart from a fraction sent by mistake and would silently make the gate unfailable. Neither field ever reinterprets a value. A per-case `passThreshold` IS a fraction; this suite/run floor is not.",
      "properties": {
        "minimumPassRatePercent": {
          "type": "number",
          "minimum": 0,
          "maximum": 100,
          "description": "A percent in [0, 100]. The whole range is usable, sub-1 values included \u2014 the unit is in the field name, so nothing is ambiguous. Note that the GitHub Checks gate rounds the measured rate to an integer before comparing (to stay in step with the eval UI), so a floor below 0.5 behaves there as if it were 0.5; the platform's own verdict compares unrounded."
        },
        "minimumPassRate": {
          "type": "number",
          "minimum": 0,
          "maximum": 100,
          "deprecated": true,
          "description": "Deprecated alias for `minimumPassRatePercent`, same unit. A value in (0, 1) is REJECTED here \u2014 it reads as a fraction sent by mistake \u2014 which is what the `not` below expresses. Use `minimumPassRatePercent` for a genuine sub-1% floor.",
          "not": {
            "exclusiveMinimum": 0,
            "exclusiveMaximum": 1
          }
        }
      },
      "oneOf": [
        {
          "required": [
            "minimumPassRatePercent"
          ]
        },
        {
          "required": [
            "minimumPassRate"
          ]
        }
      ],
      "additionalProperties": false
    },
    "tags": {
      "type": "array",
      "description": "Accepted for forward-compat; not persisted today (no-op).",
      "items": {
        "type": "string"
      }
    },
    "tests": {
      "type": "array",
      "minItems": 1,
      "maxItems": 100,
      "description": "Test cases to create in the suite. The object is CLOSED: an unknown key is a VALIDATION_ERROR, never a silently dropped field. `repetitions`, `passThreshold` and `kind` are per-case policy fields this surface cannot author \u2014 set them through `POST /v1/projects/{projectId}/eval-suites/{suiteId}/cases`.",
      "items": {
        "type": "object",
        "required": [
          "title",
          "steps"
        ],
        "allOf": [
          {
            "not": {
              "required": [
                "runs",
                "iterations"
              ]
            }
          },
          {
            "not": {
              "required": [
                "isNegative",
                "isNegativeTest"
              ]
            }
          },
          {
            "not": {
              "required": [
                "checks",
                "predicates"
              ]
            }
          }
        ],
        "properties": {
          "title": {
            "type": "string",
            "minLength": 1
          },
          "steps": {
            "type": "array",
            "minItems": 1,
            "description": "Ordered test steps (the unified test model). The first `prompt` step is the case query; `toolCalledWith` asserts are the expected tool calls; a single model-free `toolCall` step is a render-check.",
            "items": {
              "$ref": "#/components/schemas/EvalTestStep"
            }
          },
          "runs": {
            "type": "integer",
            "minimum": 1,
            "maximum": 10,
            "description": "Iterations to execute for this case. Defaults to 1."
          },
          "model": {
            "type": "string",
            "description": "Per-case model override. Defaults to the suite-level `model`."
          },
          "provider": {
            "type": "string",
            "description": "Per-case provider override."
          },
          "expectedOutput": {
            "type": "string"
          },
          "isNegativeTest": {
            "type": "boolean",
            "description": "When `true`, the case passes if NO tools are called."
          },
          "scenario": {
            "type": "string"
          },
          "advancedConfig": {
            "type": "object",
            "description": "Optional `system`, `temperature`, `toolChoice` overrides. `reasoningEffort` is NOT accepted (`400`): nothing ever applied it. Save an effort as `models[].selection.settings.reasoningEffort` instead.",
            "additionalProperties": true
          },
          "intent": {
            "type": "string",
            "minLength": 1,
            "maxLength": 64,
            "description": "Optional authored analytics grouping label."
          },
          "matchOptions": {
            "type": "object",
            "description": "Per-case tool-call matching override, in either vocabulary: public (`toolCallOrder: any|in-order|exact`, `extraToolCalls`, `arguments`) or internal (`toolCallOrder: ignore|superset|strict`, `maxExtraToolCalls`, `argumentMatching`), never both in one object.",
            "additionalProperties": true
          },
          "predicates": {
            "type": "object",
            "deprecated": true,
            "description": "DEPRECATED spelling of `checks`, which means exactly this. It was accepted here all along and never written down, passing only because this schema allowed unknown properties; documented rather than removed so no caller already sending it breaks. Send one or the other, never both.",
            "properties": {
              "mode": {
                "type": "string",
                "enum": [
                  "inherit",
                  "replace",
                  "extend"
                ]
              },
              "list": {
                "type": "array",
                "items": {
                  "type": "object"
                }
              }
            }
          },
          "isNegative": {
            "type": "boolean",
            "description": "Alias for `isNegativeTest` \u2014 the public case-authoring spelling this API returns on a read. Send one or the other, never both."
          },
          "iterations": {
            "type": "integer",
            "minimum": 1,
            "maximum": 10,
            "description": "Alias for `runs`. Send one or the other, never both."
          },
          "checks": {
            "type": "object",
            "description": "Per-case CHECK gate \u2014 the grading rules this case is scored against. `mode` says how they combine with the suite's own: `inherit` uses the suite's, `replace` uses only `list`, `extend` appends `list` to the suite's. Same field, same shape and same name as `checks` on the eval-case routes, so authoring a suite and then editing one of its cases is one word for one concept. Send this or the deprecated `predicates`, never both.",
            "properties": {
              "mode": {
                "type": "string",
                "enum": [
                  "inherit",
                  "replace",
                  "extend"
                ]
              },
              "list": {
                "type": "array",
                "items": {
                  "$ref": "#/components/schemas/EvalAssertion"
                }
              }
            }
          },
          "suppressedSuiteStandardCheckIds": {
            "$ref": "#/components/schemas/SuppressedSuiteStandardCheckIds",
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false
}

